#!/usr/bin/env python3

from __future__ import annotations

import json
import re
from html import unescape
from pathlib import Path
from typing import Any


TASK_ID = "CSX-092_Q1"
EVENT_ID = "CSX-092"


def load_json(package_dir: Path, relative_path: str) -> Any:
    with (package_dir / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def load_text(package_dir: Path, relative_path: str) -> str:
    return unescape((package_dir / relative_path).read_text(encoding="utf-8", errors="replace"))


def compact_text(html: str) -> str:
    text = re.sub(r"<[^>]+>", " ", html)
    return re.sub(r"\s+", " ", text)


def rolling_window(values: list[float], window: int) -> tuple[int, float]:
    best_index = 0
    best_total = sum(values[:window])
    for index in range(1, len(values) - window + 1):
        total = sum(values[index : index + window])
        if total > best_total:
            best_index = index
            best_total = total
    return best_index, best_total


def rounded(value: float, digits: int) -> float:
    return round(float(value), digits)


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    workspace_root = task_dir.parents[2]
    package_dir = workspace_root / "event_packages" / "standard_event_packages" / "packages" / "CSX-092"

    anchor_path = "data/event_reports/event_reports_003_Locked_event_anchor_June_2013_Uttarakhand_Himalayan_floods.json"
    open_meteo_path = "data/physical_hazard/physical_hazard_003_Open-Meteo_historical_weather_point_API.json"
    nasa_report_path = "data/event_reports/event_reports_004_NASA_Earth_Observatory_-_Severe_flooding_in_Northern_India_and_Nepal.html"

    anchor = load_json(package_dir, anchor_path)
    open_meteo = load_json(package_dir, open_meteo_path)
    nasa_report_text = compact_text(load_text(package_dir, nasa_report_path))
    heavy_reference_match = re.search(r"greater than\s+([0-9]+(?:\.[0-9]+)?)\s+millimeters", nasa_report_text, flags=re.I)
    if not heavy_reference_match:
        raise ValueError("Could not extract heavy-rain map lower-bound reference from NASA report")
    report_heavy_reference_mm = float(heavy_reference_match.group(1))

    hourly = open_meteo["hourly"]
    times = hourly["time"]
    precipitation = [float(value or 0.0) for value in hourly["precipitation"]]

    event_total = sum(precipitation)
    wettest_start, wettest_total = rolling_window(precipitation, 72)
    peak_hour = max(precipitation)
    wet_hours = sum(1 for value in precipitation if value >= 0.1)

    primary_answer = {
        "answer": "persistent_multiday_monsoon_forcing",
        "event_total_mm": rounded(event_total, 1),
        "wettest_72h_mm": rounded(wettest_total, 1),
        "wettest_72h_window": f"{times[wettest_start]}/{times[wettest_start + 71]}",
        "wettest_72h_share": rounded(wettest_total / event_total, 3),
        "wet_hour_fraction": rounded(wet_hours / len(precipitation), 3),
        "peak_hour_share": rounded(peak_hour / event_total, 3),
        "report_heavy_map_gap_mm": rounded(report_heavy_reference_mm - event_total, 1),
    }

    rubric = {
        "total_points": 20,
        "criteria": [
            {
                "name": "Final consistency label",
                "points": 3,
                "description": (
                    "Uses the expected persistence label, or a clearly equivalent label, to reject a "
                    "single-hour-burst summary."
                ),
                "partial_credit": (
                    "Award 1-2 points for identifying multi-day rainfall but giving an ambiguous or overly broad label."
                ),
            },
            {
                "name": "Event total and window sum",
                "points": 4,
                "description": "Reports 133.3 mm total precipitation and 109.0 mm for the wettest 72-hour window.",
                "partial_credit": (
                    "Award 1-3 points for one correct value, small rounding mistakes, or correct formulas with a minor extraction error."
                ),
            },
            {
                "name": "Window timing",
                "points": 3,
                "description": "Identifies the wettest 72-hour window as 2013-06-15T00:00 through 2013-06-17T23:00.",
                "partial_credit": "Award 1-2 points for the correct three calendar days without exact hourly endpoints.",
            },
            {
                "name": "Ratio calculations",
                "points": 4,
                "description": "Gives ratios near 0.818 for the 72-hour share, 0.812 for wet-hour fraction, and 0.047 for peak-hour share.",
                "partial_credit": "Award 1-3 points for two correct ratios, incorrect rounding, or one arithmetic mistake.",
            },
            {
                "name": "Report-map threshold contrast",
                "points": 3,
                "description": "Computes the minimum 166.7 mm gap between the local event total and the report-extracted greater-than-300 mm heavy-rain reference.",
                "partial_credit": "Award 1-2 points for recognizing the higher map reference but omitting or misrounding the gap.",
            },
            {
                "name": "Formula-linked interpretation",
                "points": 2,
                "description": (
                    "Explains that high wet-hour and 72-hour shares, together with a small peak-hour share, support a "
                    "persistence-dominated rainfall state."
                ),
                "partial_credit": "Award 1 point for a correct interpretation that cites only one ratio.",
            },
            {
                "name": "Output discipline",
                "points": 1,
                "description": "Returns the requested compact JSON fields without unrelated management guidance or broad causal narration.",
                "partial_credit": "No partial credit; award the point only when the output stays focused on the ledger.",
            },
        ],
    }

    computed_gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": "window_threshold_reconstruction",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_answer,
        "key_values": {
            "event_window": anchor["temporal_window"],
            "hourly_record_count": len(precipitation),
            "wet_hours_ge_0_1mm": wet_hours,
            "peak_hour_mm": rounded(peak_hour, 1),
            "peak_hour_time": times[precipitation.index(peak_hour)],
            "report_heavy_reference_mm": report_heavy_reference_mm,
            "report_heavy_reference_extraction": "greater than 300 millimeters",
        },
        "tolerances": {
            "millimeter_fields": 0.1,
            "ratio_fields": 0.001,
        },
        "rubric": rubric,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                anchor_path,
                open_meteo_path,
                nasa_report_path,
            ],
        },
    }

    with (task_dir / "computed_gt.json").open("w", encoding="utf-8") as handle:
        json.dump(computed_gt, handle, indent=2, sort_keys=True)
        handle.write("\n")


if __name__ == "__main__":
    main()
